import { useState } from "react";
import Navbar from "./components/Navbar";
import LoginPage from "./components/LoginPage";

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  function handleLogin({ email }) {
    console.log("Logging in:", email);
    setIsLoggedIn(true);
    // TODO: call your real backend here, e.g.:
    // fetch("/api/auth/login", { method: "POST", body: JSON.stringify({ email, password }) })
  }

  return (
    <div className="app">
      <Navbar isLoggedIn={isLoggedIn} onLoginClick={() => setIsLoggedIn(false)} />
      {!isLoggedIn && <LoginPage onLogin={handleLogin} />}
      {isLoggedIn && <p style={{ padding: 24 }}>You're logged in 🎉</p>}
    </div>
  );
}
